import json
from pathlib import Path
matches = []
for path in sorted(Path('world/pages').glob('missions-*.json')):
    data = json.loads(path.read_text())
    def visit(value):
        if isinstance(value, dict):
            if value.get('mission_id') in {'QUEBEC-DISCRETE-DATA-QA-QUOTE', 'MUNICIPAL-CAD-DATA-HANDOFF'} and 'goal' in value:
                matches.append({key: value.get(key) for key in ('mission_id', 'goal', 'status', 'evidence')})
            else:
                for item in value.values():
                    visit(item)
        elif isinstance(value, list):
            for item in value:
                visit(item)
    visit(data)
print(json.dumps(matches, ensure_ascii=False))
